WITH customer_returns AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender, COUNT(*) AS return_count, SUM(wr.wr_return_amt) AS total_return_amt FROM web_returns wr JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk JOIN customer_demographics cd ON wr.wr_refunded_cdemo_sk = cd.cd_demo_sk JOIN customer_address ca ON wr.wr_refunded_addr_sk = ca.ca_address_sk GROUP BY c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender ) SELECT cr.c_customer_sk, cr.c_first_name, cr.c_last_name, cr.ca_country, cr.cd_gender, cr.return_count, cr.total_return_amt, NTILE(4) OVER (ORDER BY cr.total_return_amt DESC) AS return_quartile FROM customer_returns cr WHERE cr.return_count >= 10 ORDER BY cr.return_count DESC
